import { editProjectBallotTemplate } from '~/client';
import type { EditProjectBallotTemplateRequest, EditProjectBallotTemplateResponse } from '~/client';

export const useEditProjectBallotTemplate = defineMutation(() => {
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (params: {
      data: EditProjectBallotTemplateRequest;
      projectId: string;
    }): Promise<EditProjectBallotTemplateResponse> =>
      editProjectBallotTemplate({
        composable: '$fetch',
        path: { project_id: params.projectId },
        body: ref(params.data),
      }),
    onSuccess: (_, params) => {
      const queryCache = useQueryCache();
      queryCache.invalidateQueries({
        key: ['project-ballot-template', params.projectId],
      });
      queryCache.invalidateQueries({ key: ['project-edit-tabs-status', params.projectId] });
      showToastSuccess(`Petition template uploaded successfully`);
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    uploadProjectBallotTemplate: mutateAsync,
    isUploadingProjectBallotTemplateLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
