<template>
  <form id="editProjectBallotTemplateForm" class="grid grid-cols-2 gap-6" @submit="onSubmit">
    <FormItemWrapper name="name" label="Petition Template Name">
      <template #default="{ slots }">
        <Input id="name" type="text" v-bind="slots.componentField" />
      </template>
    </FormItemWrapper>
    <FormItemWrapper name="s3_url">
      <template #default="{ slots }">
        <KitFormFileUpload
          form-id="project-edit-vdb-file-upload"
          :file-types="['application/pdf']"
          :file-size-limit="50"
          size-unit="MB"
          @on-process-data="
            (value) => {
              if (value) {
                slots.setValue(value.privateUrl, false);
              } else {
                slots.setValue(undefined, false);
              }
            }
          "
        />
      </template>
    </FormItemWrapper>
    <div class="col-start-2 flex justify-end">
      <Button form="editProjectBallotTemplateForm" :loading="isUploadingProjectBallotTemplatePdfLoading">Submit</Button>
    </div>
  </form>
</template>

<script setup lang="ts">
import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import { useUploadProjectBallotTemplatePdf } from '~/mutations/project/edit/uploadBallotTemplatePdf';

const inputSchema = toTypedSchema(
  z.object({
    name: z
      .string({ message: 'Petition Template Name is required' })
      .trim()
      .nonempty('Petition Template Name is required')
      .max(255, 'Petition Template Name must be less than 255 characters'),
    s3_url: z.string({ message: 'Petition template file is required' }).nonempty('Petition template file is required'),
  })
);

const { handleSubmit, setFieldValue, values } = useForm({
  validationSchema: inputSchema,
});

const { uploadProjectBallotTemplatePdf, isUploadingProjectBallotTemplatePdfLoading } =
  useUploadProjectBallotTemplatePdf();

const onSubmit = handleSubmit(async (values) => {
  await uploadProjectBallotTemplatePdf({
    data: {
      name: values.name,
      s3_url: values.s3_url,
    },
    projectId: useRoute('projects-id-edit-ballot-template').params.id as string,
  });
});
</script>
