<template>
  <Button class="w-fit" @click="onClick">Upload New File</Button>
</template>

<script setup lang="ts">
import type { GetProjectBallotTemplateResponse } from '~/client';

function onClick() {
  const queryCache = useQueryCache();
  const projectId = useRoute('projects-id-edit-ballot-template').params.id as string;
  const data = queryCache.getQueryData<GetProjectBallotTemplateResponse>(['project-ballot-template', projectId]);
  queryCache.setQueryData(['project-ballot-template', projectId], () => {
    return {
      ...data,
      state: null,
      pages: [],
      name: data?.name,
    };
  });
}
</script>
