import { editProjectBallotTemplatePdf } from '~/client';
import type { EditProjectBallotTemplatePdfRequest, EditProjectBallotTemplatePdfResponse } from '~/client';

export const useUploadProjectBallotTemplatePdf = defineMutation(() => {
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (params: {
      data: EditProjectBallotTemplatePdfRequest;
      projectId: string;
    }): Promise<EditProjectBallotTemplatePdfResponse> =>
      editProjectBallotTemplatePdf({
        composable: '$fetch',
        path: { project_id: params.projectId },
        body: params.data,
      }),
    onSuccess: (_, params) => {
      const queryCache = useQueryCache();
      queryCache.invalidateQueries({
        key: ['project-ballot-template', params.projectId],
      });
      showToastSuccess(`Petition template PDF uploaded successfully`);
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    uploadProjectBallotTemplatePdf: mutateAsync,
    isUploadingProjectBallotTemplatePdfLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
