<template>
  <div class="w-full relative">
    <div
      ref="containerRef"
      :class="[
        'w-full h-full relative border',
        imageStatus === 'ready' ? (editMode ? 'cursor-grab' : 'cursor-crosshair') : '',
      ]"
    >
      <AppLoader v-if="imageStatus === 'pending'" variant="inline" subject="petition template image" />
      <AppError
        v-else-if="imageStatus === 'error'"
        title=""
        message="Failed to load petition template image"
        variant="table"
        :action-text="null"
      />
      <v-stage
        v-else-if="imageStatus === 'ready'"
        ref="stageRef"
        :config="stageConfig"
        @mousedown="onPointerDown"
        @mousemove="onPointerMove"
        @mouseup="onPointerUp"
        @pointerleave="
          () => {
            if (drawing) isLeavedWithPointer = page.template_page_index;
          }
        "
        @click="onStageClick"
      >
        <v-layer>
          <v-image :config="imageConfig" />
        </v-layer>
        <v-layer>
          <v-group
            v-for="table in tables"
            :key="table.id"
            :config="{ x: table.x, y: table.y, draggable: editMode, name: table.id }"
            @click="(e: Konva.KonvaEventObject<PointerEvent>) => selectShape(e, table, 'table')"
            @dragmove="(e: Konva.KonvaEventObject<PointerEvent>) => onDragGroup(e, table)"
            @dragend="() => onDragEnd()"
          >
            <v-rect :config="{ width: table.w, height: table.h, stroke: '#0000AB', strokeWidth: 2 }" />
            <v-label :config="{ x: 4, y: 4 }">
              <v-tag
                :config="{
                  fill: 'rgba(255,255,255,0.8)',
                  stroke: 'gray',
                  strokeWidth: 1,
                  cornerRadius: 3,
                  padding: 4,
                }"
              />
              <v-text
                :config="{
                  text: table.label || 'No Label',
                  fontSize: labelsConfig.fontSize,
                  fill: 'black',
                  padding: labelsConfig.padding,
                }"
              />
            </v-label>
            <v-group
              v-for="row in table.rows"
              :key="row.id"
              :config="{ x: row.x, y: row.y, draggable: editMode, name: row.id }"
              @click="(e: Konva.KonvaEventObject<PointerEvent>) => selectShape(e, row, 'row', table)"
              @dragmove="(e: Konva.KonvaEventObject<PointerEvent>) => onDragGroup(e, row, table)"
            >
              <v-rect :config="{ width: row.w, height: row.h, stroke: '#1AD277', strokeWidth: 2 }" />
              <v-label :config="{ x: 4, y: 4 }">
                <v-tag
                  :config="{
                    fill: 'rgba(255,255,255,0.8)',
                    stroke: 'gray',
                    strokeWidth: 1,
                    cornerRadius: 3,
                    padding: 4,
                  }"
                />
                <v-text
                  :config="{
                    text: row.label || 'No Label',
                    fontSize: labelsConfig.fontSize,
                    fill: 'black',
                    padding: labelsConfig.padding,
                  }"
                />
              </v-label>
              <v-group
                v-for="sig in row.sigs"
                :key="sig.id"
                :config="{ x: sig.x, y: sig.y, draggable: editMode, name: sig.id }"
                @click="(e: Konva.KonvaEventObject<PointerEvent>) => selectShape(e, sig, 'signature', row)"
                @dragmove="(e: Konva.KonvaEventObject<PointerEvent>) => onDragGroup(e, sig, row)"
              >
                <v-rect :config="{ width: sig.w, height: sig.h, stroke: '#FF0BFF', strokeWidth: 2 }" />
                <v-label :config="{ x: 4, y: 4 }">
                  <v-tag
                    :config="{
                      fill: 'rgba(255,255,255,0.8)',
                      stroke: 'gray',
                      strokeWidth: 1,
                      cornerRadius: 3,
                      padding: 4,
                    }"
                  />
                  <v-text
                    :config="{
                      text: sig.label || 'No Label',
                      fontSize: labelsConfig.fontSize,
                      fill: 'black',
                      padding: labelsConfig.padding,
                    }"
                  />
                </v-label>
              </v-group>
            </v-group>
          </v-group>
          <v-transformer
            ref="transformerRef"
            :config="transformerConfig"
            @transformend="onTransformEnd"
            @transform="onTransform"
          />
        </v-layer>
      </v-stage>
      <div
        v-if="editMode && selected && selected.pageIndex === page.template_page_index"
        class="absolute flex items-center space-x-4 bg-white rounded-md shadow-md py-1 px-2"
        :style="{
          top: `${toolbarScreenPos.y}px`,
          left: `${toolbarScreenPos.x}px`,
        }"
      >
        <Button
          variant="outline"
          size="sm"
          @click="
            async () => {
              if (selected) await deleteItem(selected?.model.id, selected.type, selected.parent);
            }
          "
        >
          <Trash class="w-4 h-4 cursor-pointer" />
        </Button>
        <div v-if="selected.type && selected.type !== 'table'" class="flex gap-2 items-center">
          <Button variant="outline" size="sm" :disabled="!canGenerate" @click="onAIGeneratedClick">Auto-fill</Button>
          <Input
            v-if="
              selected.type === 'row' &&
              selected.parent &&
              'rows' in selected.parent &&
              selected.parent?.rows.length < 2
            "
            v-model="rowsToAdd"
            v-maska
            placeholder="# Rows"
            class="w-20 h-8"
            data-maska-number
          />
        </div>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, reactive, computed, onMounted, onUnmounted } from 'vue';
import type { BallotTemplatePageOutput } from '~/client';
import Konva from 'konva';
import type { Node } from 'konva/lib/Node';
import type {
  RectModel,
  RowModel,
  TableModel,
  Pending,
  Drawing,
  SelectedModel,
  RectTypes,
} from '@/types/projects/labeling';
import { Trash } from 'lucide-vue-next';

const pending = ref<Pending | null>(null);
const drawing = ref<Drawing | null>(null);
const isLeavedWithPointer = ref<number | null>(null);

const props = defineProps<{
  page: BallotTemplatePageOutput;
  selected: SelectedModel | null;
  mode: 'edit' | RectTypes;
}>();

interface PageSnapshot {
  pageIndex: number;
  tables: TableModel[];
}

const emits = defineEmits<{
  (e: 'update-selected-value', value: SelectedModel | null): void;
  (e: 'add-to-history', value: PageSnapshot): void;
  (e: 'page-ready', value: PageSnapshot): void;
  (e: 'update-mode', value: 'edit' | RectTypes): void;
}>();

useEventListener(document, 'mouseup', (evt) => {
  if (isLeavedWithPointer.value === props.page.template_page_index && drawing.value) {
    emits('add-to-history', { pageIndex: props.page.template_page_index, tables });
    isLeavedWithPointer.value = null;
    drawing.value = null;
  }
});

const { width } = useWindowSize();
const labelsConfig = computed(() => {
  if (width.value < 1230) {
    return {
      fontSize: 10,
      padding: 3,
    };
  } else {
    return {
      fontSize: 14,
      padding: 4,
    };
  }
});

const labelsId = ref<Record<RectTypes, number>>({
  table: 0,
  row: 0,
  signature: 0,
});

const tables = reactive<TableModel[]>([]);
const toolbarScreenPos = ref({ x: 0, y: 0 });

const toolbarWidth = computed(() => {
  return props.selected?.type === 'table' ? 60 : 160;
});
const toolbarHeight = 32;
const GAP = 24;

const rowsToAdd = ref<number | null>(0);

watch(
  () => props.selected,
  async (sel) => {
    await updateToolbarPosition(sel);
  },
  { immediate: true }
);

async function setDataFromHistory(pageIndex: number, newTables: TableModel[]) {
  const oldSel = props.selected;
  tables.splice(0, tables.length, ...newTables);

  if (oldSel && oldSel.pageIndex === pageIndex) {
    let newSelected: SelectedModel | null = null;

    if (oldSel.type === 'table') {
      const tbl = tables.find((t) => t.id === oldSel.model.id);
      if (tbl) {
        newSelected = { ...oldSel, model: tbl };
      }
    } else if (oldSel.type === 'row') {
      for (const t of tables) {
        const r = t.rows.find((rr) => rr.id === oldSel.model.id);
        if (r) {
          newSelected = { ...oldSel, model: r, parent: t };
          break;
        }
      }
    } else if (oldSel.type === 'signature') {
      for (const t of tables) {
        for (const r of t.rows) {
          const s = r.sigs.find((ss) => ss.id === oldSel.model.id);
          if (s) {
            newSelected = { ...oldSel, model: s, parent: r };
            break;
          }
        }
        if (newSelected) break;
      }
    }

    emits('update-selected-value', newSelected);
  } else {
    if (props.selected && props.selected.pageIndex === pageIndex) emits('update-selected-value', null);
  }

  await nextTick();
  const stage = stageRef.value?.getStage?.();
  if (stage) stage.batchDraw();

  if (transformerRef.value && props.selected) {
    const tr = transformerRef.value.getNode() as Konva.Transformer;
    const node = stage?.findOne((n: any) => n.name() === props.selected?.model.id);
    tr.nodes(node ? [node] : []);
    tr.getLayer()?.batchDraw();
  }

  await updateToolbarPosition(props.selected);
}

async function updateToolbarPosition(sel: SelectedModel | null) {
  await nextTick();
  if (!sel || !stageRef.value || !containerRef.value) return;

  const stage = stageRef.value.getStage()!;
  const node = stage.findOne((n: any) => n.name() === sel.model.id) as Konva.Group;
  if (!node) return;

  const box = node.getClientRect({ relativeTo: stage });

  const stageRect = stage.container().getBoundingClientRect();
  const containerRect = containerRef.value.getBoundingClientRect();

  const absX = stageRect.left + box.x + box.width / 2 - toolbarWidth.value / 2;
  const absYAbove = stageRect.top + box.y - toolbarHeight - GAP;
  const absYBelow = stageRect.top + box.y + box.height + GAP;

  const absY = absYAbove - containerRect.top >= 0 ? absYAbove : absYBelow;

  let x = absX - containerRect.left;
  let y = absY - containerRect.top;

  const maxX = containerRect.width - toolbarWidth.value;
  const maxY = containerRect.height - toolbarHeight;
  x = Math.min(Math.max(0, x), maxX);
  y = Math.min(Math.max(0, y), maxY);

  toolbarScreenPos.value = { x, y };
}

const editMode = computed(() => props.mode === 'edit');

watch(
  () => props.mode,
  (mode) => {
    if (mode !== 'edit') {
      emits('update-selected-value', null);
    }
    const stage = stageRef.value?.getStage();
    if (stage) stage.batchDraw();
  }
);

const containerRef = ref<HTMLElement | null>(null);
const stageRef = ref<Konva.Stage | null>(null);
const natural = reactive({ width: 0, height: 0 });
const stageConfig = reactive<Konva.StageConfig>({ width: 0, height: 0 });
const imageElem = ref<HTMLImageElement | null>(null);
const imageConfig = computed<Konva.ImageConfig>(() => ({
  image: imageElem.value || undefined,
  width: stageConfig.width,
  height: stageConfig.height,
}));

defineExpose({
  tables: tables,
  pageIndex: props.page.template_page_index,
  natural: natural,
  stageConfig: stageConfig,
  setDataFromHistory: setDataFromHistory,
});

const transformerConfig = reactive({
  enabledAnchors: [
    'top-left',
    'top-center',
    'top-right',
    'middle-left',
    'middle-right',
    'bottom-left',
    'bottom-center',
    'bottom-right',
  ],
  rotateEnabled: false,
  anchorSize: 10,
  ignoreStroke: true,

  boundBoxFunc: (
    oldBox: { x: number; y: number; width: number; height: number },
    newBox: { x: number; y: number; width: number; height: number }
  ) => {
    let parentX = 0;
    let parentY = 0;
    let parentW = stageConfig.width || 0;
    let parentH = stageConfig.height || 0;

    if (props.selected) {
      const { type, parent } = props.selected;
      if (type === 'row' && parent) {
        parentX = parent.x;
        parentY = parent.y;
        parentW = parent.w;
        parentH = parent.h;
      }
      if (type === 'signature' && parent) {
        const table = tables.find((t) => t.rows.includes(parent as any))!;
        parentX = table.x + parent.x;
        parentY = table.y + parent.y;
        parentW = parent.w;
        parentH = parent.h;
      }
    }

    newBox.x = Math.max(newBox.x, parentX);
    newBox.y = Math.max(newBox.y, parentY);
    newBox.width = Math.min(newBox.width, parentX + parentW - newBox.x);
    newBox.height = Math.min(newBox.height, parentY + parentH - newBox.y);

    return newBox;
  },
});

function updateStageSize() {
  if (!containerRef.value || !natural.width) return;

  const newW = containerRef.value.clientWidth;
  const newH = Math.round((natural.height / natural.width) * newW);

  const oldW = stageConfig.width ?? newW;
  const oldH = stageConfig.height ?? newH;

  const scaleX = newW / oldW;
  const scaleY = newH / oldH;

  stageConfig.width = newW;
  stageConfig.height = newH;

  tables.forEach((t) => {
    t.x *= scaleX;
    t.y *= scaleY;
    t.w *= scaleX;
    t.h *= scaleY;

    t.rows.forEach((r) => {
      r.x *= scaleX;
      r.y *= scaleY;
      r.w *= scaleX;
      r.h *= scaleY;

      r.sigs.forEach((s) => {
        s.x *= scaleX;
        s.y *= scaleY;
        s.w *= scaleX;
        s.h *= scaleY;
      });
    });
  });
}

const imageStatus = ref<'ready' | 'pending' | 'error'>('pending');

let resizeObserver: ResizeObserver;

onMounted(() => {
  const img = new Image();
  img.src = props.page.image_url;
  img.onload = () => {
    imageStatus.value = 'ready';
    natural.width = img.naturalWidth;
    natural.height = img.naturalHeight;
    imageElem.value = img;
    updateStageSize();
    const displaySize = { width: stageConfig.width ?? 0, height: stageConfig.height ?? 0 };
    const naturalSize = { width: natural.width ?? 0, height: natural.height ?? 0 };
    tables.splice(0, tables.length, ...convertPageOutputToTableModels(props.page, displaySize, naturalSize));
    fillIDsCounter2();
    emits('page-ready', {
      pageIndex: props.page.template_page_index,
      tables: tables,
    });
  };
  img.onerror = () => {
    imageStatus.value = 'error';
  };
  resizeObserver = new ResizeObserver(updateStageSize);
  if (containerRef.value) resizeObserver.observe(containerRef.value);
});

onUnmounted(() => {
  resizeObserver.disconnect();
});

//Counter by amount
function fillIDsCounter() {
  labelsId.value.table = tables.length + 1;
  labelsId.value.row = tables.reduce((sum, t) => sum + t.rows.length, 0) + 1;
  labelsId.value.signature =
    tables.reduce((sum, t) => sum + t.rows.reduce((rowSum, r) => rowSum + r.sigs.length, 0), 0) + 1;
}

//Counter by trailing number
function fillIDsCounter2() {
  function getTrailingNumber(label: string | undefined): number {
    if (!label) return 0;
    const match = label.match(/(\d+)\s*$/);
    return match ? parseInt(match[1], 10) : 0;
  }

  labelsId.value.table = Math.max(0, ...tables.map((t) => getTrailingNumber(t.label))) + 1;

  labelsId.value.row = Math.max(0, ...tables.flatMap((t) => t.rows.map((r) => getTrailingNumber(r.label)))) + 1;

  labelsId.value.signature =
    Math.max(0, ...tables.flatMap((t) => t.rows.flatMap((r) => r.sigs.map((s) => getTrailingNumber(s.label))))) + 1;
}

const SNAP_DIST = 12;

function onDragGroup(e: Konva.KonvaEventObject<PointerEvent>, item: RectModel, parent?: TableModel | RowModel) {
  const group = e.currentTarget as Konva.Group;
  const stage = stageRef.value!.getStage()!;

  let newX = group.x();
  let newY = group.y();
  if (!parent) {
    const maxX = stage.width() - item.w;
    const maxY = stage.height() - item.h;
    newX = Math.min(Math.max(newX, 0), maxX);
    newY = Math.min(Math.max(newY, 0), maxY);

    group.x(newX);
    group.y(newY);
    item.x = newX;
    item.y = newY;

    const snapXs = tables.filter((t) => t.id !== item.id).flatMap((t) => [t.x, t.x + t.w]);
    const snapYs = tables.filter((t) => t.id !== item.id).flatMap((t) => [t.y, t.y + t.h]);
    item.x = snapToNearest(item.x, snapXs, SNAP_DIST);
    item.y = snapToNearest(item.y, snapYs, SNAP_DIST);
    group.x(item.x);
    group.y(item.y);

    stage.batchDraw();
    updateToolbarPosition(props.selected);
    return;
  }

  const maxX = parent.w - item.w;
  const maxY = parent.h - item.h;
  newX = Math.min(Math.max(newX, 0), maxX);
  newY = Math.min(Math.max(newY, 0), maxY);

  const snapXs: number[] = [0, maxX];
  const snapYs: number[] = [0, maxY];

  if ('rows' in parent) {
    for (const r of parent.rows) {
      if (r.id === item.id) continue;
      snapYs.push(r.y, r.y + item.h);
      snapYs.push(r.y, r.y - item.h);
      snapXs.push(r.x, r.x + item.w);
      snapXs.push(r.x, r.x - item.w);
    }
  } else if ('sigs' in parent) {
    for (const s of parent.sigs) {
      if (s.id === item.id) continue;
      snapXs.push(s.x, s.x + item.w);
      snapXs.push(s.x, s.x - item.w);
      snapYs.push(s.y, s.y + item.h);
      snapYs.push(s.y, s.y - item.h);
    }
  }

  newX = snapToNearest(newX, snapXs, SNAP_DIST);
  newY = snapToNearest(newY, snapYs, SNAP_DIST);

  group.x(newX);
  group.y(newY);
  item.x = newX;
  item.y = newY;

  updateToolbarPosition(props.selected);
}

function onDragEnd() {
  emits('add-to-history', { pageIndex: props.page.template_page_index, tables });
}

function onPointerDown(evt: Konva.KonvaEventObject<PointerEvent>) {
  pending.value = null;
  drawing.value = null;
  if (props.mode === 'edit') return;

  const stage = evt.target.getStage()!;
  let pos = stage.getPointerPosition()!;

  let list: RectModel[] | null = null;
  let parentTable: TableModel | undefined;
  let parentRow: RowModel | undefined;

  if (props.mode === 'table') {
    if (tables.length > 0) {
      showToastError('Cannot add a new table, one already exists on this page.', 'Table Limit Reached');
      return;
    }
    const hit = tables.find((t) => pos.x >= t.x && pos.x <= t.x + t.w && pos.y >= t.y && pos.y <= t.y + t.h);
    if (hit) return;

    list = tables;
  } else if (props.mode === 'row') {
    const table = tables.find((t) => pos.x >= t.x && pos.x <= t.x + t.w && pos.y >= t.y && pos.y <= t.y + t.h);
    if (!table) {
      showToastError('Cannot add a new row outside of a table.', 'Incorrect row placement');
      return;
    }

    const localX = pos.x - table.x;
    const localY = pos.y - table.y;

    const clickedExistingRow = table.rows.some(
      (r) => localX >= r.x && localX <= r.x + r.w && localY >= r.y && localY <= r.y + r.h
    );
    if (clickedExistingRow) {
      showToastError('Cannot add a new row inside an existing row.', 'Incorrect row placement');
      return;
    }

    parentTable = table;
    list = table.rows;
    pos = { x: localX, y: localY };
  } else if (props.mode === 'signature') {
    for (const t of tables) {
      const r = t.rows.find(
        (r) => pos.x >= t.x + r.x && pos.x <= t.x + r.x + r.w && pos.y >= t.y + r.y && pos.y <= t.y + r.y + r.h
      );
      if (!r) continue;

      if (r.sigs.length > 0) {
        showToastError('Cannot add a new signature, one already exists in this row.', 'Signature Limit Reached');
        return;
      }

      const localX = pos.x - t.x - r.x;
      const localY = pos.y - t.y - r.y;

      if (r.sigs.some((s) => localX >= s.x && localX <= s.x + s.w && localY >= s.y && localY <= s.y + s.h)) {
        showToastError('Cannot add a new signature inside an existing signature.', 'Incorrect signature placement');
        return;
      }

      parentTable = t;
      parentRow = r;
      list = r.sigs;
      pos = { x: localX, y: localY };
      break;
    }
    if (!list) {
      showToastError('Signature can be added only inside a row.', 'Incorrect signature placement');
      return;
    }
  }

  if (!list) return;

  pending.value = {
    x0: pos.x,
    y0: pos.y,
    list,
    parentTable,
    parentRow,
    type: props.mode,
  };
}

function onPointerMove(evt: Konva.KonvaEventObject<PointerEvent>) {
  const native = evt.evt as MouseEvent;
  if (native.buttons === 0) {
    pending.value = null;
    return;
  }

  const stage = evt.target.getStage()!;
  const pos = stage.getPointerPosition()!;

  if (pending.value && !drawing.value) {
    const dx = pos.x - pending.value.x0;
    const dy = pos.y - pending.value.y0;
    if (Math.hypot(dx, dy) > 4) {
      const baseRect: RectModel = {
        id: crypto.randomUUID(),
        x: pending.value.x0,
        y: pending.value.y0,
        w: 0,
        h: 0,
        label: `${props.mode}${props.mode !== 'edit' ? ' ' + labelsId.value[props.mode]++ : ''}`,
      };
      let shape: RectModel | RowModel | TableModel;
      if (props.mode === 'table') shape = { ...baseRect, rows: [] };
      else if (props.mode === 'row') shape = { ...baseRect, sigs: [] };
      else shape = baseRect;

      pending.value.list.push(shape as any);
      drawing.value = { ...pending.value, rect: shape };
      pending.value = null;
      stage.batchDraw();
    }
  }
  if (!drawing.value) return;

  const { parentTable, parentRow, x0, y0, rect } = drawing.value;
  let offsetX = 0,
    offsetY = 0;
  if (props.mode === 'row' && parentTable) {
    offsetX = parentTable.x;
    offsetY = parentTable.y;
  } else if (props.mode === 'signature' && parentTable && parentRow) {
    offsetX = parentTable.x + parentRow.x;
    offsetY = parentTable.y + parentRow.y;
  }
  const x0Abs = x0 + offsetX;
  const y0Abs = y0 + offsetY;

  let pMinX: number, pMaxX: number, pMinY: number, pMaxY: number;
  const boundsX: number[] = [];
  const boundsY: number[] = [];

  if (props.mode === 'table') {
    pMinX = 0;
    pMaxX = stage.width();
    pMinY = 0;
    pMaxY = stage.height();
    for (const t of tables) {
      if (t.id === rect.id) continue;
      boundsX.push(t.x, t.x + t.w);
      boundsY.push(t.y, t.y + t.h);
    }
  } else if (props.mode === 'row' && parentTable) {
    pMinX = parentTable.x;
    pMaxX = parentTable.x + parentTable.w;
    pMinY = parentTable.y;
    pMaxY = parentTable.y + parentTable.h;
    for (const r of parentTable.rows) {
      if (r.id === rect.id) continue;
      const absX = parentTable.x + r.x;
      const absY = parentTable.y + r.y;
      boundsX.push(absX, absX + r.w);
      boundsY.push(absY, absY + r.h);
    }
  } else if (props.mode === 'signature' && parentTable && parentRow) {
    pMinX = parentTable.x + parentRow.x;
    pMaxX = parentTable.x + parentRow.x + parentRow.w;
    pMinY = parentTable.y + parentRow.y;
    pMaxY = parentTable.y + parentRow.y + parentRow.h;
    for (const s of parentRow.sigs) {
      if (s.id === rect.id) continue;
      const absX = parentTable.x + parentRow.x + s.x;
      const absY = parentTable.y + parentRow.y + s.y;
      boundsX.push(absX, absX + s.w);
      boundsY.push(absY, absY + s.h);
    }
  } else {
    pMinX = 0;
    pMaxX = stage.width();
    pMinY = 0;
    pMaxY = stage.height();
  }

  boundsX.push(pMinX, pMaxX);
  boundsY.push(pMinY, pMaxY);

  let absX = clamp(pos.x, pMinX, pMaxX);
  let absY = clamp(pos.y, pMinY, pMaxY);

  if (absX > x0Abs) {
    const rights = boundsX.filter((e) => e > x0Abs);
    if (rights.length) absX = Math.min(absX, Math.min(...rights));
  } else {
    const lefts = boundsX.filter((e) => e < x0Abs);
    if (lefts.length) absX = Math.max(absX, Math.max(...lefts));
  }
  if (absY > y0Abs) {
    const bots = boundsY.filter((e) => e > y0Abs);
    if (bots.length) absY = Math.min(absY, Math.min(...bots));
  } else {
    const tops = boundsY.filter((e) => e < y0Abs);
    if (tops.length) absY = Math.max(absY, Math.max(...tops));
  }

  absX = snapToNearest(absX, boundsX, SNAP_DIST);
  absY = snapToNearest(absY, boundsY, SNAP_DIST);

  const relX = absX - offsetX;
  const relY = absY - offsetY;
  const newW = relX - x0;
  const newH = relY - y0;

  if (newW < 0) {
    rect.x = x0 + newW;
    rect.w = -newW;
  } else {
    rect.x = x0;
    rect.w = newW;
  }
  if (newH < 0) {
    rect.y = y0 + newH;
    rect.h = -newH;
  } else {
    rect.y = y0;
    rect.h = newH;
  }

  stage.batchDraw();
}

function clamp(v: number, min: number, max: number) {
  return Math.min(Math.max(v, min), max);
}

function snapToNearest(v: number, targets: number[], thresh: number) {
  let bestDelta = thresh;
  let best: number | null = null;
  for (const t of targets) {
    const d = Math.abs(v - t);
    if (d < bestDelta) {
      bestDelta = d;
      best = t;
    }
  }
  return best !== null ? best : v;
}

function onPointerUp(evt: Konva.KonvaEventObject<PointerEvent>) {
  if (!drawing.value) return;
  pending.value = null;
  const { rect, parentTable, parentRow, x0, y0 } = drawing.value;
  const stage = evt.target.getStage()!;

  let offsetX = 0,
    offsetY = 0;
  if (props.mode === 'row' && parentTable) {
    offsetX = parentTable.x;
    offsetY = parentTable.y;
  } else if (props.mode === 'signature' && parentTable && parentRow) {
    offsetX = parentTable.x + parentRow.x;
    offsetY = parentTable.y + parentRow.y;
  }

  const boundsX: number[] = [];
  const boundsY: number[] = [];
  let pMinX: number, pMaxX: number, pMinY: number, pMaxY: number;

  if (props.mode === 'table') {
    pMinX = 0;
    pMaxX = stage.width();
    pMinY = 0;
    pMaxY = stage.height();
    for (const t of tables) {
      if (t.id === rect.id) continue;
      boundsX.push(t.x, t.x + t.w);
      boundsY.push(t.y, t.y + t.h);
    }
  } else if (props.mode === 'row' && parentTable) {
    pMinX = parentTable.x;
    pMaxX = parentTable.x + parentTable.w;
    pMinY = parentTable.y;
    pMaxY = parentTable.y + parentTable.h;
    for (const r of parentTable.rows) {
      if (r.id === rect.id) continue;
      const absX = parentTable.x + r.x;
      const absY = parentTable.y + r.y;
      boundsX.push(absX, absX + r.w);
      boundsY.push(absY, absY + r.h);
    }
  } else if (props.mode === 'signature' && parentTable && parentRow) {
    pMinX = parentTable.x + parentRow.x;
    pMaxX = parentTable.x + parentRow.x + parentRow.w;
    pMinY = parentTable.y + parentRow.y;
    pMaxY = parentTable.y + parentRow.y + parentRow.h;
    for (const s of parentRow.sigs) {
      if (s.id === rect.id) continue;
      const absX = parentTable.x + parentRow.x + s.x;
      const absY = parentTable.y + parentRow.y + s.y;
      boundsX.push(absX, absX + s.w);
      boundsY.push(absY, absY + s.h);
    }
  } else {
    pMinX = 0;
    pMaxX = stage.width();
    pMinY = 0;
    pMaxY = stage.height();
  }

  boundsX.push(pMinX, pMaxX);
  boundsY.push(pMinY, pMaxY);

  const leftAbs = rect.x + offsetX;
  const topAbs = rect.y + offsetY;
  const rightAbs = rect.x + rect.w + offsetX;
  const bottomAbs = rect.y + rect.h + offsetY;

  const snapLeft = snapToNearest(leftAbs, boundsX, SNAP_DIST);
  const snapRight = snapToNearest(rightAbs, boundsX, SNAP_DIST);
  const snapTop = snapToNearest(topAbs, boundsY, SNAP_DIST);
  const snapBottom = snapToNearest(bottomAbs, boundsY, SNAP_DIST);

  rect.x = snapLeft - offsetX;
  rect.y = snapTop - offsetY;
  rect.w = snapRight - snapLeft;
  rect.h = snapBottom - snapTop;

  stage.batchDraw();
  if (['table', 'signature'].includes(drawing.value.type)) emits('update-mode', 'edit');
  pending.value = drawing.value = null;
  emits('add-to-history', { pageIndex: props.page.template_page_index, tables });
}

async function deleteItem(id: string, type: RectTypes, parent?: any) {
  if (type === 'table') {
    const i = tables.findIndex((t) => t.id === id);
    if (i >= 0) tables.splice(i, 1);
  }
  if (type === 'row' && parent) {
    const arr = (parent as TableModel).rows;
    const i = arr.findIndex((r) => r.id === id);
    if (i >= 0) arr.splice(i, 1);
  }
  if (type === 'signature' && parent) {
    const arr = (parent as RowModel).sigs;
    const i = arr.findIndex((s) => s.id === id);
    if (i >= 0) arr.splice(i, 1);
  }
  await nextTick();

  if (props.selected?.model.id === id) emits('update-selected-value', null);
  const stage = stageRef.value!.getStage()!;
  stage.batchDraw();
  emits('add-to-history', { pageIndex: props.page.template_page_index, tables });
}

function editLabel(e: Konva.KonvaEventObject<MouseEvent>, item: RectModel) {
  const textNode = e.target as Konva.Text;
  const stage = textNode.getStage()!;
  textNode.hide();

  const absPos = textNode.getAbsolutePosition();
  const areaPosition = stage.container().getBoundingClientRect();

  const textarea = document.createElement('textarea');
  document.body.appendChild(textarea);
  Object.assign(textarea.style, {
    position: 'absolute',
    top: `${areaPosition.top + absPos.y}px`,
    left: `${areaPosition.left + absPos.x}px`,
    boxSizing: 'content-box',
    whiteSpace: 'nowrap',
    width: '1px',
    minWidth: '50px',
    fontSize: `${textNode.fontSize()}px`,
    lineHeight: textNode.lineHeight().toString(),
    fontFamily: textNode.fontFamily(),
    padding: '4px',
    margin: '0',
    border: 'none',
    background: 'none',
    outline: 'none',
    overflow: 'hidden',
    resize: 'none',
  });

  textarea.value = item.label;
  textarea.focus();

  function onInput() {
    textarea.style.width = '1px';
    textarea.style.width = `${textarea.scrollWidth}px`;
  }
  textarea.addEventListener('input', onInput);
  onInput();

  let cleanedUp = false;
  function removeInput(commit = true) {
    if (cleanedUp) return;
    cleanedUp = true;

    if (commit) item.label = textarea.value;
    textNode.show();
    stage.batchDraw();

    textarea.removeEventListener('input', onInput);
    textarea.removeEventListener('keydown', onKeydown);
    textarea.removeEventListener('blur', onBlur);
    textarea.remove();
  }

  function onKeydown(ev: KeyboardEvent) {
    if (ev.key === 'Enter') {
      ev.preventDefault();
      removeInput(true);
    } else if (ev.key === 'Escape') {
      removeInput(false);
    }
  }
  function onBlur() {
    removeInput(true);
  }

  textarea.addEventListener('keydown', onKeydown);
  textarea.addEventListener('blur', onBlur);
}

const transformerRef = ref<Konva.Transformer | null>(null);

function selectShape(
  e: Konva.KonvaEventObject<PointerEvent>,
  model: RectModel,
  type: RectTypes,
  parent?: TableModel | RowModel
) {
  if (!editMode.value) return;
  e.cancelBubble = true;
  emits('update-selected-value', { model, type, parent, pageIndex: props.page.template_page_index });
}

function calculateRowsAmount() {
  if (!props.selected || props.selected.type !== 'row') return;
  const rowHeight = props.selected.model.h;
  const patternRow = props.selected.model as RowModel;
  const table = tables.find((t) => t.rows.includes(patternRow));
  if (!table) return;
  let rowsAmountToFit = Math.floor((table.h - (props.selected.model.y + props.selected.model.h)) / rowHeight);
  const newRowsTotalHeight = rowsAmountToFit * rowHeight;
  const unfilledSpace = table.h - (props.selected.model.y + props.selected.model.h) - newRowsTotalHeight;
  const spaceLeftPercentageToRowHeight = (unfilledSpace * 100) / rowHeight;

  if (spaceLeftPercentageToRowHeight > 50) {
    rowsAmountToFit += 1;
  }
  rowsToAdd.value = rowsAmountToFit;
}

watch(
  () => props.selected,
  (sel) => {
    const trComp = transformerRef.value;
    const stageComp = stageRef.value;
    if (!trComp || !stageComp) return;
    const tr = trComp.getNode() as Konva.Transformer;
    const stage = stageComp.getStage()!;
    if (sel) {
      const node = stage.findOne((node: Node) => node.name() === sel.model.id);
      tr.nodes(node ? [node] : []);
    } else {
      tr.nodes([]);
    }
    tr.getLayer()?.batchDraw();
    calculateRowsAmount();
  }
);

const LABEL_OFFSET = { x: 4, y: 4 };

function resetLabelsOn(group: Konva.Group) {
  group
    .find((n: Konva.Node) => n.getClassName() === 'Label')
    .forEach((lblNode) => {
      const lbl = lblNode as Konva.Label;
      lbl.x(LABEL_OFFSET.x);
      lbl.y(LABEL_OFFSET.y);
      lbl.scaleX(1);
      lbl.scaleY(1);
    });
}

function onTransform() {
  const stage = stageRef.value?.getStage();
  if (!stage) return;
  stage.batchDraw();
  updateToolbarPosition(props.selected);
}

async function onTransformEnd() {
  const sel = props.selected;
  const tr = transformerRef.value?.getNode() as Konva.Transformer | undefined;
  if (!sel || !tr) return;

  const stage = stageRef.value!.getStage()!;
  const group = tr.nodes()[0] as Konva.Group | undefined;
  if (!group) return;

  const primary = group.findOne<Konva.Rect>('Rect');
  if (!primary) return;
  const origW = primary.width();
  const origH = primary.height();

  // 2) Read the raw Konva scale
  const sx = group.scaleX();
  const sy = group.scaleY();

  let origRows: Array<{
    id: string;
    x: number;
    y: number;
    w: number;
    h: number;
    sigs: { id: string; x: number; y: number; w: number; h: number }[];
  }> = [];
  let origSigs: Array<{ id: string; x: number; y: number; w: number; h: number }> = [];

  let table: TableModel | undefined;
  let row: RowModel | undefined;
  let sig: RectModel | undefined;

  if (sel.type === 'table') {
    table = sel.model as TableModel;
    origRows = table.rows.map((r) => ({
      id: r.id,
      x: r.x,
      y: r.y,
      w: r.w,
      h: r.h,
      sigs: r.sigs.map((s) => ({ id: s.id, x: s.x, y: s.y, w: s.w, h: s.h })),
    }));
  } else if (sel.type === 'row') {
    row = sel.model as RowModel;
    origSigs = row.sigs.map((s) => ({ id: s.id, x: s.x, y: s.y, w: s.w, h: s.h }));
    table = tables.find((t) => t.rows.includes(row!));
  } else {
    sig = sel.model as RectModel;
    for (const t of tables) {
      const pr = t.rows.find((r) => r.sigs.includes(sig!));
      if (pr) {
        table = t;
        row = pr;
        break;
      }
    }
  }

  group.scaleX(1);
  group.scaleY(1);
  group.offsetX(0);
  group.offsetY(0);

  const absPos = group.getAbsolutePosition();
  const absLeft = absPos.x;
  const absTop = absPos.y;
  const absWidth = origW * sx;
  const absHeight = origH * sy;
  const absRight = absLeft + absWidth;
  const absBottom = absTop + absHeight;

  let pMinX: number, pMaxX: number, pMinY: number, pMaxY: number;
  const boundsX: number[] = [],
    boundsY: number[] = [];
  let offsetX = 0,
    offsetY = 0;

  if (sel.type === 'table') {
    pMinX = 0;
    pMaxX = stage.width();
    pMinY = 0;
    pMaxY = stage.height();
    for (const t of tables) {
      if (t !== table) {
        boundsX.push(t.x, t.x + t.w);
        boundsY.push(t.y, t.y + t.h);
      }
    }
  } else if (sel.type === 'row' && table) {
    offsetX = table.x;
    offsetY = table.y;
    pMinX = offsetX;
    pMaxX = offsetX + table.w;
    pMinY = offsetY;
    pMaxY = offsetY + table.h;
    for (const r of table.rows) {
      if (r !== row) {
        const ax = offsetX + r.x,
          ay = offsetY + r.y;
        boundsX.push(ax, ax + r.w);
        boundsY.push(ay, ay + r.h);
      }
    }
  } else if (sel.type === 'signature' && table && row) {
    offsetX = table.x + row.x;
    offsetY = table.y + row.y;
    pMinX = offsetX;
    pMaxX = offsetX + row.w;
    pMinY = offsetY;
    pMaxY = offsetY + row.h;
    for (const s of row.sigs) {
      if (s !== sig) {
        const ax = offsetX + s.x,
          ay = offsetY + s.y;
        boundsX.push(ax, ax + s.w);
        boundsY.push(ay, ay + s.h);
      }
    }
  } else {
    pMinX = 0;
    pMaxX = stage.width();
    pMinY = 0;
    pMaxY = stage.height();
  }

  boundsX.push(pMinX, pMaxX);
  boundsY.push(pMinY, pMaxY);

  const snapL = snapToNearest(absLeft, boundsX, SNAP_DIST);
  const snapR = snapToNearest(absRight, boundsX, SNAP_DIST);
  const snapT = snapToNearest(absTop, boundsY, SNAP_DIST);
  const snapB = snapToNearest(absBottom, boundsY, SNAP_DIST);

  const newX = snapL - offsetX;
  const newY = snapT - offsetY;
  const newW = snapR - snapL;
  const newH = snapB - snapT;

  const factorX = newW / origW;
  const factorY = newH / origH;

  if (sel.type === 'table' && table) {
    table.x = newX;
    table.y = newY;
    table.w = newW;
    table.h = newH;
    for (const r of table.rows) {
      const o = origRows.find((o) => o.id === r.id)!;
      r.x = o.x * factorX;
      r.y = o.y * factorY;
      r.w = o.w * factorX;
      r.h = o.h * factorY;
      for (const s of r.sigs) {
        const os = o.sigs.find((x) => x.id === s.id)!;
        s.x = os.x * factorX;
        s.y = os.y * factorY;
        s.w = os.w * factorX;
        s.h = os.h * factorY;
      }
    }
  } else if (sel.type === 'row' && row) {
    row.x = newX;
    row.y = newY;
    row.w = newW;
    row.h = newH;
    for (const s of row.sigs) {
      const o = origSigs.find((x) => x.id === s.id)!;
      s.x = o.x * factorX;
      s.y = o.y * factorY;
      s.w = o.w * factorX;
      s.h = o.h * factorY;
    }
  } else if (sel.type === 'signature' && sig) {
    sig.x = newX;
    sig.y = newY;
    sig.w = newW;
    sig.h = newH;
  }

  group.position({ x: newX, y: newY });

  await nextTick();
  stage.batchDraw();
  tr.nodes([group]);
  tr.getLayer()?.batchDraw();
  updateToolbarPosition(sel);
  emits('add-to-history', { pageIndex: props.page.template_page_index, tables });
  if (props.selected.type === 'row') {
    calculateRowsAmount();
  }
}

function onStageClick(e: Konva.KonvaEventObject<MouseEvent>) {
  emits('update-selected-value', null);
}

const canGenerate = computed(() => {
  if (!props.selected) return false;
  if (props.selected.type === 'row' || props.selected.type === 'signature') {
    return true;
  }
  return false;
});

async function onAIGeneratedClick() {
  if (!canGenerate.value) return;

  let generated = false;
  let patternRow: RowModel;
  let patternSig: RectModel | null = null;

  // figure out pattern
  if (props.selected!.type === 'signature') {
    patternSig = props.selected!.model as RectModel;
    patternRow = props.selected!.parent as RowModel;
  } else {
    patternRow = props.selected!.model as RowModel;
    if (patternRow.sigs.length > 0) {
      patternSig = patternRow.sigs[0];
    }
  }

  // find parent table
  const table = tables.find((t) => t.rows.includes(patternRow));
  if (!table) return;
  if (props.selected?.type === 'row' && table.rows.length > 1) {
    showToastError('Auto-Fill can only be used when there is a single row in the table.', 'Auto-Fill Error');
    return;
  }

  table.rows.sort((a, b) => a.y - b.y);
  const startIdx = table.rows.findIndex((r) => r === patternRow);
  if (startIdx < 0 || !props.selected) return;

  if (props.selected.type === 'signature') {
    // auto-fill signatures
    if (startIdx === table.rows.length - 1) {
      // nothing below to fill
      return;
    }

    const isSigCanBeAdded = table.rows.some((row) => row.sigs.length === 0);

    if (!isSigCanBeAdded) {
      showToastError('All rows already have signatures, cannot auto-fill.', 'Auto-Fill Error');
    }

    for (let i = startIdx + 1; i < table.rows.length; i++) {
      const row = table.rows[i] as RowModel;
      if (row.sigs.length > 0) continue;
      row.sigs.push({
        id: crypto.randomUUID(),
        x: patternSig!.x,
        y: patternSig!.y,
        w: patternSig!.w,
        h: patternSig!.h,
        label: `${patternSig!.label.split(' ')[0]} ${labelsId.value.signature++}`,
      });
      generated = true;
    }
  } else {
    // auto-fill rows (and optional sigs)
    let rowHeight = patternRow.h;
    const rowsAmountToFit =
      Number(rowsToAdd.value) || Math.floor((table.h - (props.selected.model.y + props.selected.model.h)) / rowHeight);
    const newRowsTotalHeight = rowsAmountToFit * rowHeight;
    const unfilledSpace = table.h - (props.selected.model.y + props.selected.model.h) - newRowsTotalHeight;
    const spaceLeftPercentageToRowHeight = (unfilledSpace * 100) / rowHeight;
    const parentRow = table.rows.find((r) => r === patternRow);

    rowHeight = rowHeight + unfilledSpace / (rowsAmountToFit + 1);

    if (parentRow) {
      parentRow.sigs.forEach((s) => (s.h = s.h - (parentRow.h - rowHeight)));
      parentRow.h = rowHeight;
    }

    let nextY = patternRow.y + rowHeight;
    for (let i = 0; i < rowsAmountToFit; i++) {
      const newRow: RowModel = {
        id: crypto.randomUUID(),
        x: patternRow.x,
        y: nextY,
        w: patternRow.w,
        h: rowHeight,
        label: `${patternRow.label.split(' ')[0]} ${labelsId.value.row++}`,
        sigs: [],
      };
      if (patternSig) {
        newRow.sigs.push({
          id: crypto.randomUUID(),
          x: patternSig.x,
          y: patternSig.y,
          w: patternSig.w,
          h: patternSig.h - (patternRow.h - rowHeight),
          label: `${patternSig.label.split(' ')[0]} ${labelsId.value.signature++}`,
        });
      }
      table.rows.push(newRow);
      generated = true;
      nextY += rowHeight;
    }
  }

  if (!generated) {
    // no new rows/sigs, so nothing to record
    return;
  }

  // only if we did generate anything:
  await nextTick();
  const stage = stageRef.value!.getStage()!;
  stage.batchDraw();
  const tr = transformerRef.value?.getNode() as Konva.Transformer | undefined;
  if (tr) {
    const node = stage.findOne((node: Node) => node.name() === patternRow.id);
    tr.nodes(node ? [node] : []);
    tr.getLayer()?.batchDraw();
  }

  emits('add-to-history', {
    pageIndex: props.page.template_page_index,
    tables: tables,
  });
}
</script>
