<template>
  <Card class="col-span-8">
    <CardHeader>
      <CardTitle class="flex flex-wrap justify-between gap-2">
        <span>Petition Template</span>
        <Badge v-if="state" :variant="stateVariant" class="text-base font-normal">{{ state }}</Badge>
      </CardTitle>
    </CardHeader>
    <CardContent>
      <AppLoader v-if="isLoading" variant="inline" subject="petition template information" />
      <AppError v-else-if="error" :error="error" title="Failed to load petition template information" variant="table" />
      <ProjectEditFormBTUpload v-else-if="!state" />
      <State
        v-else-if="state === 'failed'"
        title="Failed to import data"
        :icon="AlertOctagon"
        icon-class="stroke-destructive size-16 w-16"
      >
        <ProjectEditBTUploadNewFile />
      </State>
      <ProjectEditFormBTLabeling
        v-else-if="state === 'uploaded' || state === 'marked' || state === 'ready'"
        :pages="pages"
        :template-name="templateName"
      />
    </CardContent>
  </Card>
</template>

<script lang="ts" setup>
import { useProjectBallotTemplate } from '~/queries/project/edit/ballotTemplate';
import { AlertOctagon } from 'lucide-vue-next';

definePageMeta({
  backGroup: 'project-edit',
  roles: ['admin'],
  backLabel: 'project edit',
});

useSeoMeta({
  title: computed(() => 'Edit Project'),
  description: computed(() => 'Edit your project petition template here.'),
});

const { state, isLoading, error, pages, templateName } = useProjectBallotTemplate();

const stateVariant = computed(() => {
  switch (state.value) {
    case 'failed':
      return 'destructive';
    case 'uploaded':
      return 'default';
    case 'marked':
      return 'default';
    case 'ready':
      return 'success';
    default:
      return 'default';
  }
});
</script>
