<template>
  <div class="flex flex-col gap-8 w-full">
    <div class="flex flex-wrap justify-between gap-4">
      <span>Name: {{ templateName }}</span>
      <ProjectEditBTUploadNewFile />
    </div>
    <div v-if="!isMobile && !isTouchscreen && width >= 1024" class="flex flex-col gap-4">
      <Collapsible v-model="isHelpOpened" class="space-y-2">
        <Alert>
          <FileQuestionIcon />
          <CollapsibleTrigger as-child>
            <AlertTitle class="h-5 flex flex-row font-semibold items-center justify-between w-full cursor-pointer">
              <span>How to use this tool?</span>
              <ChevronDownIcon class="h-4 w-4" />
            </AlertTitle>
          </CollapsibleTrigger>
          <CollapsibleContent as-child>
            <AlertDescription>
              <div class="grid grid-cols-3 gap-4 mt-4">
                <Card>
                  <div class="flex flex-row gap-2 p-2">
                    <img src="@/assets/img/ballot-table.png" class="h-32" />
                    <div>
                      <p class="font-semibold">Step 1. Table</p>
                      <p>Draw a box that contains the whole table. There can be at most one table per page.</p>
                    </div>
                  </div>
                </Card>
                <Card>
                  <div class="flex flex-row gap-2 p-2">
                    <img src="@/assets/img/ballot-rows.png" class="h-32" />
                    <div>
                      <p class="font-semibold">Step 2. Rows</p>
                      <p>Draw boxes for rows where the voter puts their information.</p>
                    </div>
                  </div>
                </Card>
                <Card>
                  <div class="flex flex-row gap-2 p-2">
                    <img src="@/assets/img/ballot-signatures.png" class="h-32" />
                    <div>
                      <p class="font-semibold">Step 3. Signatures</p>
                      <p>Signatures are optional. Each row can contain at most one signature.</p>
                    </div>
                  </div>
                </Card>
              </div>
              <ul class="list-disc mt-4">
                <li>
                  Rows and signatures have Auto Generate buttons to fill the table with rows or fill rows with
                  signatures to the end of the table.
                </li>
                <li>Deleting an element deletes all nested elements.</li>
              </ul>
            </AlertDescription>
          </CollapsibleContent>
        </Alert>
      </Collapsible>
      <div class="w-100 flex justify-center sticky top-0 z-10 bg-white border rounded">
        <div class="flex items-center gap-8 py-4">
          <div class="flex items-center gap-2">
            <Button variant="outline" :class="{ 'border-black border-2': mode === 'edit' }" @click="mode = 'edit'"
              ><Pencil /> Edit</Button
            >
          </div>
          <div class="flex items-center gap-2">
            <Button variant="outline" :class="{ 'border-black border-2': mode === 'table' }" @click="mode = 'table'"
              ><Table /> Table</Button
            >
            <Button variant="outline" :class="{ 'border-black border-2': mode === 'row' }" @click="mode = 'row'"
              ><Rows /> Row</Button
            >
            <Button
              variant="outline"
              :class="{ 'border-black border-2': mode === 'signature' }"
              @click="mode = 'signature'"
            >
              <Signature /> Signature</Button
            >
          </div>
          <div class="flex items-center gap-2">
            <Button :disabled="historyIndex <= 0" variant="outline" @click="undoLastChange"> <Undo />Undo </Button>
            <Button :disabled="historyIndex >= history.length - 1" variant="outline" @click="redoLastChange">
              Redo<Redo />
            </Button>
          </div>
        </div>
      </div>
      <div v-if="pages" class="flex-col items-center gap-6 w-full flex">
        <ProjectEditFormBTLabelingPage2
          v-for="page in pages"
          ref="pageRefs"
          :key="page.template_page_index"
          :page="page"
          :mode="mode"
          :selected="selected"
          @update-selected-value="updateSelectedValue"
          @add-to-history="addToHistory"
          @page-ready="onPageReady"
          @update-mode="(value: 'edit' | RectTypes) => (mode = value)"
        />
        <div class="flex justify-end mt-4 w-full">
          <Button
            :loading="isUploadingProjectBallotTemplateLoading"
            :disabled="isUploadingProjectBallotTemplateLoading || isEqual(editedData, savedData) || !isPagesLoaded"
            @click="uploadTemplate"
            >Save</Button
          >
        </div>
      </div>
    </div>
    <Alert v-else>
      <FileQuestionIcon />
      <AlertTitle> Mobile view is not supported for editing </AlertTitle>
      <AlertDescription>
        This page is not optimized for mobile devices. Please use a desktop browser to edit the petition template.
      </AlertDescription>
    </Alert>
  </div>
  <NavigationGuard
    v-if="!isMobile && !isTouchscreen && savedData && isAuthenticated && isPagesLoaded"
    :saved-data="savedData"
    :changed-data="editedData"
    title="Warning"
    description="You have unsaved changes. All changes will be lost if you navigate away."
    confirm-text="Discard Changes"
  />
  <SubmitGuard
    v-if="!isValidLabeling.isValid"
    v-model="submitGuardModel"
    title="Warning"
    :description="isValidLabeling.message || ''"
  />
</template>

<script setup lang="ts">
import type { BallotTemplatePageOutput, BallotTemplatePageInput } from '~/client';
import { useEditProjectBallotTemplate } from '~/mutations/project/edit/editBallotTemplate';
import type { TableModel, SelectedModel, RectTypes } from '~/types/projects/labeling';
import { convertTablesToPageInput } from '~/utils/processBallotTemplate';
import { ChevronDownIcon, FileQuestionIcon, Undo, Redo, Pencil, Signature, Rows, Table } from 'lucide-vue-next';
import { isEqual } from 'lodash';

interface Props {
  pages: BallotTemplatePageOutput[];
  templateName: string;
}

const props = defineProps<Props>();

const { isMobile, isTouchscreen } = useMobileForWeb();
const { width } = useWindowSize();
const { isAuthenticated } = useUserRole();

interface LabelingPageExpose {
  tables: TableModel[];
  pageIndex: number;
  natural: { width: 0; height: 0 };
  stageConfig: { width: 0; height: 0 };
  setDataFromHistory: (pageIndex: number, tables: TableModel[]) => void;
}

const mode = ref<'edit' | 'table' | 'row' | 'signature'>('edit');
const pageRefs = ref<(LabelingPageExpose | null)[]>([]);
const isHelpOpened = ref<boolean>(false);
const ctrlDown = ref<boolean>(false);
const comboFired = ref<boolean>(false);

const editedData = computed<BallotTemplatePageInput[]>(() => {
  return pageRefs.value
    .filter((pr): pr is NonNullable<typeof pr> => pr != null)
    .map((pr) => {
      const result = convertTablesToPageInput(pr.tables, pr.pageIndex, pr.stageConfig, pr.natural);
      return result;
    });
});

const savedData = computed<BallotTemplatePageInput[]>(() => {
  return props.pages.map((p) => ({
    template_page_index: p.template_page_index,
    table: p.table,
    rows: p.rows,
  }));
});

const { uploadProjectBallotTemplate, isUploadingProjectBallotTemplateLoading } = useEditProjectBallotTemplate();

const submitGuardModel = ref<boolean>(false);

async function uploadTemplate() {
  submitGuardModel.value = false;
  if (isValidLabeling.value.isValid) await onSubmitGuardConfirm();
  else submitGuardModel.value = true;
}

async function onSubmitGuardConfirm() {
  if (!isValidLabeling.value.isValid) return;
  try {
    await uploadProjectBallotTemplate({
      data: { pages: editedData.value },
      projectId: useRoute('projects-id-edit-ballot-template').params.id.toString(),
    });
  } catch (error) {
    console.error('Error uploading petition template:', error);
  }
}

const isValidLabeling = computed(() => {
  const isTable = editedData.value.find((page) => {
    return page.table;
  });

  let isTableWithoutRows: boolean = false;
  editedData.value.forEach((page) => {
    if (page.table && (!page.rows || page.rows.length === 0)) isTableWithoutRows = true;
  });

  const message = isTable
    ? !isTableWithoutRows
      ? null
      : 'Tables should contain at least one row'
    : 'At least one page should contain a table labeling';

  return { isValid: Boolean(isTable && !isTableWithoutRows), message };
});

const selected = ref<SelectedModel | null>(null);

function updateSelectedValue(newValue: SelectedModel | null) {
  selected.value = newValue;
}
interface PageSnapshot {
  pageIndex: number;
  tables: TableModel[];
}

interface HistoryItem {
  pages: PageSnapshot[];
  changedPageIndex: number;
}

const history = ref<HistoryItem[]>([]);
const historyIndex = ref<number>(-1);

function clone<T>(obj: T): T {
  return JSON.parse(JSON.stringify(obj));
}

function initHistory(initialPages: PageSnapshot[]) {
  history.value = [
    {
      changedPageIndex: -1,
      pages: initialPages.map((p) => ({ pageIndex: p.pageIndex, tables: clone(p.tables) })),
    },
  ];
  historyIndex.value = 0;
}

function addToHistory(pageSnapshot: PageSnapshot) {
  if (historyIndex.value < history.value.length - 1) {
    history.value.splice(historyIndex.value + 1);
  }

  const base = clone(history.value[historyIndex.value].pages);

  const idx = base.findIndex((p) => p.pageIndex === pageSnapshot.pageIndex);
  const newEntry: PageSnapshot = {
    pageIndex: pageSnapshot.pageIndex,
    tables: clone(pageSnapshot.tables),
  };
  if (idx >= 0) base[idx] = newEntry;
  else base.push(newEntry);

  const histItem: HistoryItem = {
    pages: base,
    changedPageIndex: pageSnapshot.pageIndex,
  };
  history.value.push(histItem);
  historyIndex.value = history.value.length - 1;
}

function undoLastChange() {
  if (historyIndex.value <= 0) return;
  historyIndex.value--;
  applyHistory(history.value[historyIndex.value]);
}

function redoLastChange() {
  if (historyIndex.value >= history.value.length - 1) return;
  historyIndex.value++;
  applyHistory(history.value[historyIndex.value]);
}

function applyHistory(item: HistoryItem) {
  item.pages.forEach(({ pageIndex, tables }) => {
    const pageRef = pageRefs.value.find((r) => r?.pageIndex === pageIndex);
    if (pageRef) {
      pageRef.setDataFromHistory(pageIndex, clone(tables));
    }
  });
}

onMounted(() => {
  const initial: PageSnapshot[] = pageRefs.value
    .filter((pr): pr is NonNullable<typeof pr> => pr != null)
    .map((pr) => {
      const pageData = props.pages.find((p) => p.template_page_index === pr.pageIndex)!;
      return {
        pageIndex: pr.pageIndex,
        tables: convertPageOutputToTableModels(pageData, pr.stageConfig, pr.natural),
      };
    });
  initHistory(initial);
  window.addEventListener('keydown', onKeydown);
  window.addEventListener('keyup', onKeyup);
});

onUnmounted(() => {
  window.removeEventListener('keydown', onKeydown);
  window.removeEventListener('keyup', onKeyup);
  isPagesLoaded.value = false;
});

function cycleMode() {
  switch (mode.value) {
    case 'edit':
      mode.value = 'table';
      break;
    case 'table':
      mode.value = 'row';
      break;
    case 'row':
      mode.value = 'signature';
      break;
    case 'signature':
      mode.value = 'edit';
      break;
  }
}

function onKeydown(evt: KeyboardEvent) {
  const key = evt.key;

  if (key === 'Control' || key === 'Meta') {
    ctrlDown.value = true;
    comboFired.value = false;
    return;
  }

  if (ctrlDown.value) {
    comboFired.value = true;

    if (key.toLowerCase() === 'z') {
      evt.preventDefault();
      evt.stopImmediatePropagation();

      if (evt.shiftKey) {
        redoLastChange();
      } else {
        undoLastChange();
      }
    }
  }
}

function onKeyup(evt: KeyboardEvent) {
  const key = evt.key;

  if (key === 'Control') {
    if (!comboFired.value) {
      cycleMode();
    }
    // reset
    ctrlDown.value = false;
    comboFired.value = false;
  }
}

const readySnapshots = ref<PageSnapshot[]>([]);
const isPagesLoaded = ref<boolean>(false);

function onPageReady(snapshot: PageSnapshot) {
  readySnapshots.value.push(snapshot);
  if (readySnapshots.value.length === props.pages.length) {
    initHistory(readySnapshots.value);
    isPagesLoaded.value = true;
  }
}
</script>
